<?php
namespace Tests\Feature\Website;use App\Models\{LandingNews,LandingPageSetting,LandingProgram};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class LandingPageTest extends TestCase {use RefreshDatabase;public function test_homepage_is_public_and_has_responsive_navigation():void{LandingPageSetting::create(['key'=>'landing_enabled','value'=>'1','group'=>'publication']);LandingPageSetting::create(['key'=>'hero_title','value'=>'Hero Aktif','group'=>'hero']);$this->get('/')->assertOk()->assertSee('Hero Aktif')->assertSee('mobile-nav');}public function test_public_layout_component_can_be_rendered():void{$this->blade('<x-layouts.public title="Halaman Publik">Konten publik</x-layouts.public>')->assertSee('<title>Halaman Publik</title>',false)->assertSee('Konten publik');}public function test_only_active_program_is_visible():void{LandingProgram::create(['title'=>'Aktif','slug'=>'aktif','is_active'=>true]);LandingProgram::create(['title'=>'Rahasia','slug'=>'rahasia','is_active'=>false]);$this->get('/')->assertSee('Aktif')->assertDontSee('Rahasia');}public function test_draft_news_is_not_public_but_published_news_is():void{LandingNews::create(['title'=>'Draft Rahasia','slug'=>'draft','category'=>'Berita','content'=>'x','status'=>'draft']);LandingNews::create(['title'=>'Berita Terbit','slug'=>'terbit','category'=>'Berita','content'=>'x','status'=>'published','published_at'=>now()]);$this->get('/berita')->assertSee('Berita Terbit')->assertDontSee('Draft Rahasia');$this->get('/berita/terbit')->assertOk();$this->get('/berita/draft')->assertNotFound();}public function test_guest_cannot_manage_website():void{$this->get('/website')->assertRedirect('/login');}public function test_seo_meta_is_rendered():void{LandingPageSetting::create(['key'=>'meta_description','value'=>'Deskripsi SEO sekolah','group'=>'seo']);$this->get('/')->assertSee('Deskripsi SEO sekolah');}}
